-- One-time effects a job has already applied (T368; FR-072), generated by Prisma from schema.prisma:
-- a job that may run twice claims its effect's key in the same transaction as the effect.
-- CreateTable
CREATE TABLE "EffectMarker" (
    "key" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "EffectMarker_pkey" PRIMARY KEY ("key")
);
